INSERT INTO sys.sys_engagement_feedback
  (feedback_tenant_id, feedback_natural_key, feedback_category, feedback_message, feedback_status,
   feedback_reviewed_by_user_id, feedback_reviewed_at, feedback_action_notes, feedback_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_EFB::'||src.lid, src.category, src.message, src.status,
   rv.user_id, src.reviewed_at::timestamptz, src.action_notes,
   jsonb_strip_nulls(jsonb_build_object('legacy_feedback_id', src.lid,
     'unresolved_reviewer_employee',
       CASE WHEN src.reviewed_by_emp_lid IS NOT NULL AND rv.user_id IS NULL THEN src.reviewed_by_emp_lid END))
FROM src
LEFT JOIN sys.sys_users rv ON rv.user_external_code = 'LEGACY_EMP::' || src.reviewed_by_emp_lid
ON CONFLICT (feedback_tenant_id, feedback_natural_key) DO NOTHING;

