INSERT INTO sys.sys_engagement_action_plans
  (action_plan_tenant_id, action_plan_natural_key, action_plan_source_type, action_plan_source_id,
   action_plan_title, action_plan_description, action_plan_owner_user_id, action_plan_status,
   action_plan_priority, action_plan_due_date, action_plan_completed_at, action_plan_created_by_user_id, action_plan_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_EAP::' || src.lid, src.source_type, src.source_id::uuid,
   src.title, src.description, ow.user_id, src.status, src.priority, src.due_date::date, src.completed_at::timestamptz, cb.user_id,
   jsonb_strip_nulls(jsonb_build_object('legacy_action_plan_id', src.lid,
     'unresolved_owner_employee',
       CASE WHEN src.owner_emp_lid IS NOT NULL AND ow.user_id IS NULL THEN src.owner_emp_lid END,
     'unresolved_created_by_employee',
       CASE WHEN src.created_by_emp_lid IS NOT NULL AND cb.user_id IS NULL THEN src.created_by_emp_lid END))
FROM src
LEFT JOIN sys.sys_users ow ON ow.user_external_code = 'LEGACY_EMP::' || src.owner_emp_lid
LEFT JOIN sys.sys_users cb ON cb.user_external_code = 'LEGACY_EMP::' || src.created_by_emp_lid
ON CONFLICT (action_plan_tenant_id, action_plan_natural_key) DO NOTHING;

-- registry rows for the 2 new tables (bucket A IMPORT) — fresh-rebuild safety (mirrors 46_engagement_surveys)
INSERT INTO sys.sys_reconciliation_registry
  (reconciliation_registry_table_name, reconciliation_registry_bucket, reconciliation_registry_declared_status,
   reconciliation_registry_legacy_source, reconciliation_registry_legacy_source_rows, reconciliation_registry_rationale)
VALUES
  ('sys_engagement_feedback','A','IMPORT','engagement_feedback',685,'[S988 R1 Fase3] Anonymous engagement feedback; RTL-only import (400 of 685); reviewer via LEGACY_EMP crosswalk; submitter structurally anonymous (no legacy author column).'),
  ('sys_engagement_action_plans','A','IMPORT','engagement_action_plans',6,'[S988 R1 Fase3] Post-survey/feedback action plans; RTL-only (6 of 6); owner/created_by via LEGACY_EMP crosswalk; source_id polymorphic legacy ref.')
ON CONFLICT (reconciliation_registry_table_name) DO NOTHING;

-- post-condition (assert counts; report unresolved attribution — non-fatal)
DO $post$
DECLARE n_fb int; n_ap int; n_fb_unres int; n_ap_unres int;
BEGIN
  SELECT count(*) INTO n_fb FROM sys.sys_engagement_feedback WHERE feedback_tenant_id='86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid;
  SELECT count(*) INTO n_ap FROM sys.sys_engagement_action_plans WHERE action_plan_tenant_id='86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid;
  SELECT count(*) INTO n_fb_unres FROM sys.sys_engagement_feedback WHERE feedback_metadata ? 'unresolved_reviewer_employee';
  SELECT count(*) INTO n_ap_unres FROM sys.sys_engagement_action_plans
    WHERE action_plan_metadata ? 'unresolved_owner_employee' OR action_plan_metadata ? 'unresolved_created_by_employee';
  RAISE NOTICE '51_engagement_feedback: feedback=% action_plans=% (expect 400/6); unresolved reviewers=% action-plan-people=% (expect 0/0)',
    n_fb, n_ap, n_fb_unres, n_ap_unres;
  IF n_fb <> 400 OR n_ap <> 6 THEN
    RAISE EXCEPTION '51_engagement_feedback: count mismatch feedback=% action_plans=%', n_fb, n_ap;
  END IF;
END $post$;
COMMIT;
